CREATE TABLE qmk_campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,code text NOT NULL,name text NOT NULL,objective text,status text NOT NULL DEFAULT 'draft',starts_at timestamptz,ends_at timestamptz,owner_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),UNIQUE(org_id,code));
CREATE TABLE qmk_channels(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,code text NOT NULL,name text NOT NULL,kind text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),UNIQUE(org_id,code));
CREATE TABLE qmk_campaign_channels(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,campaign_id uuid NOT NULL,channel_id uuid NOT NULL,allocation numeric(20,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,campaign_id,channel_id),FOREIGN KEY(org_id,campaign_id) REFERENCES qmk_campaigns(org_id,id),FOREIGN KEY(org_id,channel_id) REFERENCES qmk_channels(org_id,id));
CREATE TABLE qmk_budget_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,campaign_id uuid NOT NULL,request_no text NOT NULL,amount numeric(20,2) NOT NULL,currency text NOT NULL DEFAULT 'VND',status text NOT NULL DEFAULT 'draft',workflow_instance_id uuid,requested_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),UNIQUE(org_id,request_no),FOREIGN KEY(org_id,campaign_id) REFERENCES qmk_campaigns(org_id,id));
CREATE TABLE qmk_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,campaign_id uuid,title text NOT NULL,asset_type text NOT NULL,uri text,status text NOT NULL DEFAULT 'draft',metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),FOREIGN KEY(org_id,campaign_id) REFERENCES qmk_campaigns(org_id,id));
CREATE TABLE qmk_research_projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,code text NOT NULL,title text NOT NULL,status text NOT NULL DEFAULT 'planned',owner_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),UNIQUE(org_id,code));
CREATE TABLE qmk_research_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,project_id uuid NOT NULL,title text NOT NULL,findings jsonb NOT NULL DEFAULT '{}',published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,project_id) REFERENCES qmk_research_projects(org_id,id));
CREATE TABLE qmk_product_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,product_ref text NOT NULL,positioning text,audience jsonb NOT NULL DEFAULT '{}',messaging jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,product_ref));
CREATE TABLE qmk_publications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,campaign_id uuid,channel_id uuid NOT NULL,asset_id uuid,title text NOT NULL,status text NOT NULL DEFAULT 'draft',scheduled_at timestamptz,published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),FOREIGN KEY(org_id,campaign_id) REFERENCES qmk_campaigns(org_id,id),FOREIGN KEY(org_id,channel_id) REFERENCES qmk_channels(org_id,id),FOREIGN KEY(org_id,asset_id) REFERENCES qmk_assets(org_id,id));
CREATE TABLE qmk_task_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,campaign_id uuid,title text NOT NULL,assignee_id uuid NOT NULL,status text NOT NULL DEFAULT 'open',due_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,id),FOREIGN KEY(org_id,campaign_id) REFERENCES qmk_campaigns(org_id,id));
CREATE TABLE qmk_checklist_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,task_id uuid NOT NULL,label text NOT NULL,position integer NOT NULL DEFAULT 0,done boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,task_id) REFERENCES qmk_task_assignments(org_id,id));
CREATE TABLE qmk_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',occurred_at timestamptz NOT NULL DEFAULT now());CREATE INDEX qmk_event_aggregate_idx ON qmk_events(org_id,aggregate_type,aggregate_id);
CREATE TABLE qmk_idempotency(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,scope text NOT NULL,key text NOT NULL,request_hash text NOT NULL,resource_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,scope,key));
